import{_ as i,o as a,c as t,a6 as o}from"./chunks/framework.DL_pga9_.js";const m=JSON.parse('{"title":"Standard Library Modularization","description":"","frontmatter":{},"headers":[],"relativePath":"design/archive/stdlib_modularization.md","filePath":"design/archive/stdlib_modularization.md","lastUpdated":1780030916000}'),s={name:"design/archive/stdlib_modularization.md"};function d(l,e,r,n,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="standard-library-modularization" tabindex="-1">Standard Library Modularization <a class="header-anchor" href="#standard-library-modularization" aria-label="Permalink to “Standard Library Modularization”">​</a></h1><h2 id="order" tabindex="-1">Order <a class="header-anchor" href="#order" aria-label="Permalink to “Order”">​</a></h2><p>Recommended Issue order: 9. Module-system-local order: 4.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Organize the standard library as normal source/native/bytecode modules with explicit imports and exports.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><p>Prerequisites:</p><ul><li><a href="./module_artifact_typechecker">Module Artifact And Typechecker Integration</a></li><li><a href="./native_module_artifacts">Native Module Artifacts</a></li><li><a href="./bytecode_module_loading">Bytecode Module Loading</a>, if shipping <code>.ngo</code> stdlib artifacts in the same milestone</li></ul><p>Related:</p><ul><li><a href="./../enhanced_tuples">Enhanced Tuple Types</a>, if tuple intrinsics are exposed through stdlib modules.</li><li><a href="./../auto_derive_traits">Auto Traits And Derive Traits</a>, if stdlib owns core marker traits.</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>In scope:</p><ul><li>Split stdlib into explicit modules.</li><li>Keep <code>std.prelude</code> as public facade.</li><li>Move native-backed APIs behind NG stubs plus native descriptors.</li><li>Ensure source-first and bytecode-first stdlib modes agree.</li><li>Define entrypoint prelude import policy.</li></ul><p>Out of scope:</p><ul><li>Initial artifact model.</li><li>Initial native descriptor model.</li><li>General bytecode format design.</li></ul><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to “Layout”">​</a></h2><p>Recommended layout:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lib/std/prelude.ng</span></span>
<span class="line"><span>lib/std/string.ng</span></span>
<span class="line"><span>lib/std/array.ng</span></span>
<span class="line"><span>lib/std/io.ng</span></span>
<span class="line"><span>lib/std/imgui.ng</span></span>
<span class="line"><span>native/std/prelude</span></span>
<span class="line"><span>native/std/imgui</span></span></code></pre></div><p>Optional compiled layout:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lib/std/prelude.ngo</span></span>
<span class="line"><span>lib/std/prelude.ng</span></span></code></pre></div><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to “Rules”">​</a></h2><ul><li>Prelude is imported automatically only by entrypoint policy, not hardcoded into every module artifact.</li><li><code>std.prelude</code> re-exports stable common APIs.</li><li>Re-exporting imported modules uses definition-prefix export syntax: <code>export import std.string (*);</code>.</li><li>Native-backed standard modules use NG stubs plus native descriptors.</li><li>Imported symbols are not re-exported by <code>exports *</code>; re-export is explicit.</li><li>Imported symbols retain source module provenance. Re-importing the same symbol from the same source module is idempotent; importing the same short name from different modules is a conflict unless the caller keeps the modules qualified.</li><li>Module-only imports remain the conflict-avoidance path: <code>import some.module as m; m.symbol(...)</code>.</li><li>Future short-name aliasing for individual imported symbols is tracked in <a href="./../symbol_import_aliases">Symbol Import Aliases</a>.</li><li>Standard library modules must be usable from STUPID and ORGASM.</li></ul><h2 id="native-module-shape" tabindex="-1">Native Module Shape <a class="header-anchor" href="#native-module-shape" aria-label="Permalink to “Native Module Shape”">​</a></h2><p>Implemented stdlib native modules:</p><ul><li><code>std.prelude</code>: common language/runtime helpers.</li><li><code>std.io</code>: input/output and process-adjacent helpers (<code>readLine</code>, <code>readFile</code>, <code>writeFile</code>, <code>currentExecutablePath</code>, <code>runNgi</code>).</li><li><code>std.string</code>: string helpers and regex predicate support (<code>split</code>, <code>join</code>, <code>trim</code>, <code>contains</code>, <code>replace</code>, <code>startsWith</code>, <code>endsWith</code>, <code>toUpper</code>, <code>toLower</code>, <code>regexMatch</code>).</li><li><code>std.array</code>: array-oriented helpers (<code>reverse</code>). Range, slice, and fold are language syntax rather than stdlib helper APIs.</li><li><code>std.seq</code>: <code>Sequence&lt;T&gt;</code> trait protocol for sequential containers (<code>size</code> and <code>get</code> in the current baseline).</li><li><code>std.list</code>: NG-authored linked list implementation built on tagged unions, references, inherent <code>List&lt;T&gt;</code> methods (<code>pushBack</code>, <code>append</code>, <code>get</code>), and a <code>Sequence&lt;T&gt;</code> impl. <code>listof&lt;T&gt;(args: T...)</code> provides homogeneous varargs construction; the free <code>pushBack</code>/<code>append</code>/<code>get</code> functions remain available as explicit ref-passing APIs.</li><li><code>std.memory</code>: native allocation/profiler helpers (<code>UniquePtr</code>, <code>nativeMalloc</code>, <code>nativeFree</code>, <code>nativeOutstandingAllocations</code>, <code>gcFree</code>).</li><li><code>std.imgui</code>: Dear ImGui wrapper backed by SDL3/GPU state owned by the module.</li></ul><p><code>std.prelude</code> is now a facade over the smaller std modules. It uses <code>export import std.tuple (*)</code>, <code>export import std.io (*)</code>, <code>export import std.string (*)</code>, <code>export import std.array (*)</code>, <code>export import std.seq (*)</code>, and <code>export import std.memory (*)</code> to explicitly re-export stable symbols that should remain available through entrypoint prelude loading. Direct module imports such as <code>import std.string (trim, split)</code> and <code>import std.array (reverse)</code> are supported in both STUPID and ORGASM.</p><p><code>std.imgui</code> exposes opaque NG native handle types for ImGui structures that are not owned by NG:</p><div class="language-ng"><button title="Copy Code" class="copy"></button><span class="lang">ng</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>type ImGuiContext = native;</span></span>
<span class="line"><span>type ImGuiIO = native;</span></span>
<span class="line"><span>type ImGuiStyle = native;</span></span></code></pre></div><p>The wrapper keeps SDL window/device/event ownership internal. NG code uses ImGui-like functions and handle accessors (<code>GetIO</code>, <code>GetStyle</code>, <code>ImGuiIO_*</code>, <code>ImGuiStyle_*</code>) without directly importing SDL APIs.</p><p>Current wrapper coverage includes lifecycle/frame control, context/IO/style handles, common flag constants, windows, child windows, cursor/layout, ID stack, disabled regions, tooltips, style/color stacks, text, basic widgets, input widgets, combos, selectables, tables, trees, tabs, menus, popups, and runtime queries. Mutable ImGui pointer-parameter widgets return the updated value in NG, e.g. <code>InputText(...) -&gt; string</code>, <code>DragFloat(...) -&gt; f32</code>, and <code>Checkbox(...) -&gt; bool</code>.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to “Acceptance Criteria”">​</a></h2><ul><li><code>import std.prelude (*)</code> works from source modules.</li><li>Implemented: <code>import std.string (join, split)</code> works after string APIs are moved.</li><li>Implemented: <code>import std.io (...)</code>, <code>import std.array (...)</code>, and <code>import std.memory (...)</code> resolve as source modules backed by native handlers.</li><li>Native-backed stdlib functions have NG-visible signatures.</li><li>Implemented: <code>std.imgui</code> exposes NG-visible signatures for context, IO, style, flags, windows, layout, widgets, menus, popups, and runtime query wrappers.</li><li>Examples pass with source-first stdlib resolution.</li><li>Examples pass with bytecode-first stdlib resolution when <code>.ngo</code> artifacts are present.</li><li>STUPID and ORGASM agree on exported stdlib symbols.</li></ul>`,32)])])}const h=i(s,[["render",d]]);export{m as __pageData,h as default};
